-- Blocked pin codes (BRE rule "pincode-blocked-reject", flag bre-pincode-blocked-reject, default ON).
-- A NEW customer (no loan on record, not a reborrow) whose verified pin code — the PAN record's zip,
-- the DigiLocker Aadhaar address or the geolocation address — is on this list is auto-rejected
-- permanently (reason PINCODE_BLOCKED; the borrower sees only the neutral rejection). Returning
-- borrowers and files already disbursed are never touched. ADMIN edits the list on Staff -> BRE rules;
-- this seed is the 2026-11-26 "blocked pin" sheet (10,037 unique pins).
create table blocked_pincode (
    pincode    varchar(6)   primary key check (pincode ~ '^[1-9][0-9]{5}$'),
    created_at timestamp(6) with time zone not null default now(),
    created_by varchar(255)
);

